static bool ReductionComputationsEquivalent(const HloComputation& a,
                                            const HloComputation& b) {
  if (a == b) {
    return true;
  }

  // Check for simple commutative reduction functions.
  enum CommutativeFnKind { kAdd, kMul, kAnd, kOr };
  auto categorize_computation =
      [](const HloComputation& c) -> std::optional<CommutativeFnKind> {
    if (c.num_parameters() != 2) {
      return std::nullopt;
    }

    const HloInstruction* root = c.root_instruction();
    if (Match(root, m::AddAnyOrder(m::Parameter(0), m::Parameter(1)))) {
      return kAdd;
    }
    if (Match(root, m::MultiplyAnyOrder(m::Parameter(0), m::Parameter(1)))) {
      return kMul;
    }
    if (Match(root, m::AndAnyOrder(m::Parameter(0), m::Parameter(1)))) {
      return kAnd;
    }
    if (Match(root, m::OrAnyOrder(m::Parameter(0), m::Parameter(1)))) {
      return kOr;
    }
    return std::nullopt;
  };
  auto category_a = categorize_computation(a);
  auto category_b = categorize_computation(b);
  return category_a.has_value() && category_b.has_value() &&
         category_a == category_b;
}

static bool MatchArgMinMax(const HloInstruction* hlo, bool is_max) {
  // Create matcher for shared sub-expression.
  auto value_pred = m::OrAnyOrder(
      m::Compare(m::Parameter(0), m::Parameter(2))
          .WithComparisonDirection(is_max ? ComparisonDirection::kGt
                                          : ComparisonDirection::kLt),
      m::Compare(m::Parameter(0), m::Parameter(0))
          .WithComparisonDirection(ComparisonDirection::kNe));

  // Match on argmax reduction computation.
  return Match(
      hlo,
      m::Tuple(
          m::Select(value_pred, m::Parameter(0), m::Parameter(2)),
          m::Select(
              m::OrAnyOrder(
                  value_pred,
                  m::And(
                      m::Compare(m::Parameter(0), m::Parameter(2))
                          .WithComparisonDirection(ComparisonDirection::kEq),
                      m::Compare(m::Parameter(1), m::Parameter(3))
                          .WithComparisonDirection(ComparisonDirection::kLt))),
              m::Parameter(1), m::Parameter(3))));
}

static bool MatchArgMin(const HloInstruction* hlo) {
  // Match on variadic Reduce ArgMin
  if (hlo->opcode() != HloOpcode::kReduce || hlo->operand_count() != 4 ||
      !hlo->shape().IsTuple() ||
      hlo->operand(1)->opcode() != HloOpcode::kIota ||
      !IsScalarConstantInf(hlo->operand(2)) ||
      !IsScalarConstantZero(hlo->operand(3))) {
    return false;
  }
  return MatchArgMinMax(hlo->to_apply()->root_instruction(), /*is_max=*/false);
}

static bool MatchArgMax(const HloInstruction* hlo) {
  // Match on variadic Reduce ArgMax.
  if (hlo->opcode() != HloOpcode::kReduce || hlo->operand_count() != 4 ||
      !hlo->shape().IsTuple() ||
      hlo->operand(1)->opcode() != HloOpcode::kIota ||
      !IsScalarConstantNegInf(hlo->operand(2)) ||
      !IsScalarConstantZero(hlo->operand(3))) {
    return false;
  }
  return MatchArgMinMax(hlo->to_apply()->root_instruction(), /*is_max=*/true);
}

int64_t GetReduceFlops(const HloInstruction* reduce) {
  int64_t reduce_product = 1;
  for (int64_t dim : reduce->dimensions()) {
    reduce_product *= reduce->operand(0)->shape().dimensions(dim);
  }
  // Reduce along a dimension of size n requires n-1 reductions
  return ShapeUtil::ElementsIn(reduce->shape()) * (reduce_product - 1);
}

std::pair<std::vector<int64_t>, std::vector<int64_t>> ConstructFromDotMaps(
    const HloInstruction* dot, const Shape& a_shape, const Shape& b_shape) {
  // Reserve space for new maps
  std::vector<int64_t> map_ab_a(dot->shape().dimensions().size(), -1),
      map_ab_b(dot->shape().dimensions().size(), -1);
  // Construct the maps going in the opposite direction
  std::vector<int64_t> map_a_ab, map_b_ab;
  std::tie(map_a_ab, map_b_ab) =
      ConstructToDotMaps(dot->dot_dimension_numbers(), a_shape, b_shape);
  // Construct these maps by inverting those above
  int64_t a_index = 0;
  for (auto ab_index : map_a_ab) {
    if (ab_index != -1) {
      map_ab_a[ab_index] = a_index;
    }
    a_index++;
  }
  int64_t b_index = 0;
  for (auto ab_index : map_b_ab) {
    if (ab_index != -1) {
      map_ab_b[ab_index] = b_index;
    }
    b_index++;
  }
  return {map_ab_a, map_ab_b};
}

absl::Status AlgebraicSimplifierVisitor::BroadcastReduce(
    const Shape& reduce_result_shape, bool multi_output_reduce,
    HloReduceInstruction* reduce) {
  auto init_values = reduce->init_values();
  auto init_for_single_output = init_values[0];
  if (multi_output_reduce) {
    std::vector<HloInstruction*> broadcast_inits;
    int64_t inputs = reduce->input_count();
    broadcast_inits.reserve(inputs);
    for (int64_t i = 0; i < inputs; ++i) {
      broadcast_inits.push_back(
          init_values[i]->AddInstruction(HloInstruction::CreateBroadcast(
              reduce->shape().tuple_shapes(i), init_values[i], {})));
    }
    return ReplaceWithNewInstruction(
        reduce, HloInstruction::CreateTuple(broadcast_inits));
  }

  return ReplaceWithNewInstruction(
      reduce, HloInstruction::CreateBroadcast(reduce_result_shape,
                                              init_for_single_output, {}));
}

absl::Status AlgebraicSimplifierVisitor::ReplaceReduceWithReshape(
    const Shape& reduce_result_shape, bool multi_output_reduce,
    HloReduceInstruction* reduce) {
  auto init_for_single_output = reduce->inputs()[0];
  if (multi_output_reduce) {
    std::vector<HloInstruction*> reshaped_args;
    auto reduce_inputs = reduce->inputs();
    int64_t inputs = reduce->input_count();
    reshaped_args.reserve(inputs);
    for (int64_t i = 0; i < inputs; ++i) {
      reshaped_args.push_back(
          reduce->AddInstruction(HloInstruction::CreateReshape(
              reduce->shape().tuple_shapes(i), reduce_inputs[i])));
    }
    return ReplaceWithNewInstruction(
        reduce, HloInstruction::CreateTuple(reshaped_args));
  }

  return ReplaceWithNewInstruction(
      reduce, HloInstruction::CreateReshape(reduce_result_shape,
                                            init_for_single_output));
}

absl::Status AlgebraicSimplifierVisitor::MergeReduces(
    const Shape& reduce_result_shape, HloInstruction* init_value,
    HloComputation* function, HloInstruction* arg,
    HloReduceInstruction* reduce) {
  // Create a new reduce with the combined reduction dimensions of both
  // reduces.
  std::vector<int64_t> arg_dims = *arg->mutable_dimensions();
  absl::c_sort(arg_dims);
  std::vector<int64_t> reduce_dims = *reduce->mutable_dimensions();
  absl::c_sort(reduce_dims);
  // Transform reduce_dims to the same rank as the operand of the operand.
  // TODO(b/411670134): No need to iterate as the vectors are sorted.
  for (int64_t arg_dim : arg_dims) {
    for (int64_t& dim : reduce_dims) {
      if (dim >= arg_dim) {
        ++dim;
      }
    }
  }
  std::vector<int64_t> new_dimensions;
  new_dimensions.reserve(arg->dimensions().size() +
                         reduce->dimensions().size());
  std::merge(arg_dims.begin(), arg_dims.end(), reduce_dims.begin(),
             reduce_dims.end(), std::back_inserter(new_dimensions));
  return ReplaceWithNewInstruction(
      reduce,
      HloInstruction::CreateReduce(reduce_result_shape, arg->mutable_operand(0),
                                   init_value, new_dimensions, function));
}

std::optional<absl::Status>
AlgebraicSimplifierVisitor::ReorderReduceDotToDotReduce(
    HloInstruction* arg, HloInstruction* init_value, HloComputation* function,
    HloReduceInstruction* reduce) {
  if (options_.raise_slice_and_reduce_through_dot()) {
    HloInstruction *a, *b;
    // Reordering does not seem possible if the dot has batch dimensions. We
    // also need the reduction operation to be add, and the reduce to have an
    // initial value of 0.
    if (Match(arg, m::Dot(m::Op(&a), m::Op(&b))) &&
        IsScalarConstantZero(init_value) &&
        Match(reduce->to_apply()->root_instruction(),
              m::AddAnyOrder(m::Parameter(0), m::Parameter(1))) &&
        arg->dot_dimension_numbers().lhs_batch_dimensions().empty()) {
      // Create maps for converting AB dimensions to A and B
      DotDimensionNumbers ab_dnums = arg->dot_dimension_numbers();
      std::vector<int64_t> map_ab_a, map_ab_b;
      std::tie(map_ab_a, map_ab_b) =
          ConstructFromDotMaps(arg, a->shape(), b->shape());

      // Create new reduce dimensions using the maps
      std::vector<int64_t> reduce_a_dims, reduce_b_dims;
      for (int64_t dim : reduce->dimensions()) {
        if (map_ab_a[dim] != -1) {
          reduce_a_dims.push_back(map_ab_a[dim]);
        }
        if (map_ab_b[dim] != -1) {
          reduce_b_dims.push_back(map_ab_b[dim]);
        }
      }

      // Create Hlo for reducing a and b
      ABSL_ASSIGN_OR_RETURN(
          HloInstruction * reduce_a,
          MakeReduceHlo(a, init_value, reduce_a_dims, function));
      ABSL_ASSIGN_OR_RETURN(
          HloInstruction * reduce_b,
          MakeReduceHlo(b, init_value, reduce_b_dims, function));

      // Construct maps from reduce_a and reduce_b to a and b
      std::vector<int64_t> map_reduce_a_a(reduce_a->shape().dimensions().size(),
                                          -1),
          map_reduce_b_b(reduce_b->shape().dimensions().size(), -1);
      int64_t reduce_a_index = 0;
      for (int64_t a_index = 0; a_index < a->shape().dimensions().size();
           ++a_index) {
        if (!absl::c_linear_search(reduce_a_dims, a_index)) {
          map_reduce_a_a[reduce_a_index] = a_index;
          ++reduce_a_index;
        }
      }
      int64_t reduce_b_index = 0;
      for (int64_t b_index = 0; b_index < b->shape().dimensions().size();
           ++b_index) {
        if (!absl::c_linear_search(reduce_b_dims, b_index)) {
          map_reduce_b_b[reduce_b_index] = b_index;
          ++reduce_b_index;
        }
      }

      // Construct dot dimension numbers for new dot
      const auto& a_contracting_dims = ab_dnums.lhs_contracting_dimensions();
      const auto& b_contracting_dims = ab_dnums.rhs_contracting_dimensions();
      DotDimensionNumbers new_dot_dnums;
      for (int64_t reduce_a_index = 0;
           reduce_a_index < reduce_a->shape().dimensions().size();
           ++reduce_a_index) {
        if (map_reduce_a_a[reduce_a_index] != -1) {
          int64_t a_index = map_reduce_a_a[reduce_a_index];
          if (absl::c_linear_search(a_contracting_dims, a_index)) {
            new_dot_dnums.add_lhs_contracting_dimensions(reduce_a_index);
          }
        }
      }
      for (int64_t reduce_b_index = 0;
           reduce_b_index < reduce_b->shape().dimensions().size();
           ++reduce_b_index) {
        if (map_reduce_b_b[reduce_b_index] != -1) {
          int64_t b_index = map_reduce_b_b[reduce_b_index];
          if (absl::c_linear_search(b_contracting_dims, b_index)) {
            new_dot_dnums.add_rhs_contracting_dimensions(reduce_b_index);
          }
        }
      }

      // Create Hlo for new dot
      ABSL_ASSIGN_OR_RETURN(
          HloInstruction * new_dot,
          MakeDotHlo(reduce_a, reduce_b, new_dot_dnums, arg->precision_config(),
                     reduce->shape().element_type()));

      // Compute the number of flops for both old and new operations
      const int64_t old_flops =
          HloCostAnalysis::GetDotFlops(a->shape(), arg->shape(), ab_dnums) +
          GetReduceFlops(reduce);
      const int64_t new_flops =
          GetReduceFlops(reduce_a) + GetReduceFlops(reduce_b) +
          HloCostAnalysis::GetDotFlops(reduce_a->shape(), new_dot->shape(),
                                       new_dot_dnums);

      // Only reorder if it would result in sufficiently fewer flops
      if (old_flops / static_cast<double>(new_flops) >
          options_.raise_slice_and_reduce_through_dot_threshold()) {
        VLOG(10) << "Reordering reduce into dot operands";
        return ReplaceInstruction(reduce, new_dot);
      }
    }
  }
  return std::nullopt;
}

auto is_same_type_bitcast = [](const HloInstruction* instr) {
  return instr->opcode() == HloOpcode::kBitcast &&
         instr->shape().element_type() ==
             instr->operand(0)->shape().element_type();
};
HloInstruction* real_operand = operand;
while (real_operand->opcode() == HloOpcode::kReshape ||
       is_same_type_bitcast(real_operand) ||
       real_operand->opcode() == HloOpcode::kConvert ||
       real_operand->opcode() == HloOpcode::kSlice ||
       real_operand->opcode() == HloOpcode::kCopy) {
  real_operand = real_operand->mutable_operand(0);
}

if (real_operand->opcode() == HloOpcode::kBroadcast &&
    ShapeUtil::IsScalar(real_operand->operand(0)->shape()) &&
    IsScalarConstantZero(init_value) &&
    Match(function->root_instruction(),
          m::AddAnyOrder(m::Parameter(0), m::Parameter(1)))) {
  HloInstruction* val_const = real_operand->mutable_operand(0);
  while (val_const->opcode() == HloOpcode::kConvert ||
         val_const->opcode() == HloOpcode::kReshape ||
         is_same_type_bitcast(val_const)) {
    val_const = val_const->mutable_operand(0);
  }

  if (!val_const->IsConstant()) {
    return absl::OkStatus();
  }

  int64_t reduction_dim = -1;
  bool valid_pattern = true;

  for (int64_t i = 0; i < window.dimensions_size(); ++i) {
    const auto& dim = window.dimensions(i);
    if (dim.size() > 1) {
      if (reduction_dim != -1) {
        // More than one reduction dimension, not supported for now.
        valid_pattern = false;
        break;
      }
      reduction_dim = i;
      // Check if it is a cumsum-like pattern:
      // - Window size matches operand size in this dimension.
      // - Stride is 1.
      // - Padding low is size - 1 (so we start with 1 element).
      // - Padding high is 0.
      // - No dilations or reversals.
      if (dim.size() != operand->shape().dimensions(i) || dim.stride() != 1 ||
          dim.padding_low() != dim.size() - 1 || dim.padding_high() != 0 ||
          dim.window_dilation() != 1 || dim.base_dilation() != 1 ||
          dim.window_reversal()) {
        valid_pattern = false;
        break;
      }
    } else {
      if (dim.padding_low() != 0 || dim.padding_high() != 0 ||
          dim.base_dilation() != 1) {
        valid_pattern = false;
        break;
      }
    }
  }

  if (valid_pattern && reduction_dim != -1) {
    TF_RET_CHECK(ShapeUtil::IsEffectiveScalar(val_const->shape()));
    absl::InlinedVector<PrimitiveType, 4> convert_types;
    for (const HloInstruction* i = operand; i != val_const;
         i = i->operand(0)) {
      if (i->opcode() == HloOpcode::kConvert) {
        convert_types.push_back(i->shape().element_type());
      }
    }
    if (!ShapeUtil::IsScalar(val_const->shape()) || !convert_types.empty()) {
      Literal scalar =
          LiteralUtil::GetFirstScalarLiteral(val_const->literal());
      for (auto it = convert_types.rbegin(); it != convert_types.rend();
           ++it) {
        ABSL_ASSIGN_OR_RETURN(scalar, scalar.Convert(*it));
      }
      val_const = reduce_window->AddInstruction(
          HloInstruction::CreateConstant(std::move(scalar)));
    }

    // Create iota for the reduction dimension.
    PrimitiveType iota_type = S32;
    if (val_const->shape().element_type() == S64) {
      iota_type = S64;
    }
    Shape iota_shape =
        ShapeUtil::ChangeElementType(reduce_window->shape(), iota_type);
    HloInstruction* iota = reduce_window->AddInstruction(
        HloInstruction::CreateIota(iota_shape, reduction_dim));

    // iota + 1
    HloInstruction* one = reduce_window->AddInstruction(
        HloInstruction::CreateConstant(LiteralUtil::One(iota_type)));
    HloInstruction* one_bcast = reduce_window->AddInstruction(
        HloInstruction::CreateBroadcast(iota_shape, one, {}));
    HloInstruction* count =
        reduce_window->AddInstruction(HloInstruction::CreateBinary(
            iota_shape, HloOpcode::kAdd, iota, one_bcast));

    // Cast count to operand type if necessary.
    if (val_const->shape().element_type() != iota_type) {
      count = reduce_window->AddInstruction(HloInstruction::CreateConvert(
          ShapeUtil::ChangeElementType(iota_shape,
                                       val_const->shape().element_type()),
          count));
    }

    // Result = val_const * count
    HloInstruction* val_bcast =
        reduce_window->AddInstruction(HloInstruction::CreateBroadcast(
            reduce_window->shape(), val_const, {}));

    return ReplaceWithNewInstruction(
        reduce_window,
        HloInstruction::CreateBinary(reduce_window->shape(),
                                     HloOpcode::kMultiply, val_bcast, count));
  }
}

if (absl::c_all_of(window.dimensions(),
                   [](const WindowDimension& dim) {
                     return dim.size() == 1 &&             //
                            dim.stride() == 1 &&           //
                            dim.window_dilation() == 1 &&  //
                            dim.base_dilation() == 1 &&    //
                            !dim.window_reversal();
                   }) &&
    Match(function->root_instruction(),
          m::AnyOf<HloInstruction>(
              m::AddAnyOrder(m::Parameter(0), m::Parameter(1)),
              m::MinimumAnyOrder(m::Parameter(0), m::Parameter(1)),
              m::MaximumAnyOrder(m::Parameter(0), m::Parameter(1))))) {
  // Apply the positive window padding amounts with a pad and the negative
  // amounts (a crop) with a slice.
  PaddingConfig padding_config;
  bool has_positive_padding = false;
  bool has_negative_padding = false;
  for (const WindowDimension& window_dim : window.dimensions()) {
    auto& padding_dim = *padding_config.add_dimensions();
    padding_dim.set_edge_padding_low(
        std::max<int64_t>(window_dim.padding_low(), 0));
    padding_dim.set_edge_padding_high(
        std::max<int64_t>(window_dim.padding_high(), 0));
    padding_dim.set_interior_padding(0);
    has_positive_padding |=
        window_dim.padding_low() > 0 || window_dim.padding_high() > 0;
    has_negative_padding |=
        window_dim.padding_low() < 0 || window_dim.padding_high() < 0;
  }

  std::vector<int64_t> start_indices;
  std::vector<int64_t> limit_indices;
  if (has_negative_padding) {
    // Negative padding crops relative to the runtime size of a dynamic
    // dimension, and the slice covers every dimension of the operand, so it
    // cannot express the crop if any dimension is dynamic.
    if (operand->shape().is_dynamic()) {
      return absl::OkStatus();
    }
    for (int64_t i = 0; i < window.dimensions_size(); ++i) {
      const WindowDimension& window_dim = window.dimensions(i);
      const int64_t dim_size = operand->shape().dimensions(i);
      // A crop of at least the whole dimension leaves no operand element in
      // the output: every output element lies in the padding and equals the
      // init value.
      if (-window_dim.padding_low() >= dim_size ||
          -window_dim.padding_high() >= dim_size) {
        return ReplaceWithNewInstruction(
            reduce_window, HloInstruction::CreateBroadcast(
                               reduce_window->shape(), init_value, {}));
      }
      start_indices.push_back(
          std::max<int64_t>(-window_dim.padding_low(), 0));
      limit_indices.push_back(
          dim_size + std::min<int64_t>(window_dim.padding_high(), 0));
    }
  }

  const HloInstruction* nested_root = function->root_instruction();
  DimensionVector broadcast_dims(nested_root->shape().dimensions().size());
  absl::c_iota(broadcast_dims, 0);
  ABSL_ASSIGN_OR_RETURN(
      auto new_op, MakeBinaryHlo(nested_root->opcode(), operand,
                                 MakeBroadcastHlo(init_value, broadcast_dims,
                                                  operand->shape())));

  // The slice goes before the pad so that later passes can sink it into the
  // elementwise op.
  if (has_negative_padding) {
    std::vector<int64_t> strides(start_indices.size(), 1);
    ABSL_ASSIGN_OR_RETURN(
        new_op, MakeSliceHlo(new_op, start_indices, limit_indices, strides));
  }
  if (has_positive_padding) {
    ABSL_ASSIGN_OR_RETURN(new_op,
                          MakePadHlo(new_op, init_value, padding_config));
  }

  return ReplaceInstruction(reduce_window, new_op);
}

  // This optimization folds a pad op into reduce_window.
  HloInstruction* pad;
  const HloInstruction* convert = nullptr;
  if (operand->opcode() == HloOpcode::kPad) {
    pad = operand;
  } else if (operand->opcode() == HloOpcode::kConvert &&
             operand->operand(0)->opcode() == HloOpcode::kPad) {
    convert = operand;
    pad = operand->mutable_operand(0);

    // TODO(b/214340779): This is a temporary hack to avoid folding pad into
    // reduce-window. We need to get AssociativeScan to work first.
    std::vector<int64_t> non_trivial_window_dimensions =
        reduce_window->non_trivial_window_dimensions();

    // If there is only one non-trivial dimension, we can check if the padding
    // ratio is big enough to justify the optimization.
    if (non_trivial_window_dimensions.size() == 1) {
      int64_t non_trivial_window_dimension = non_trivial_window_dimensions[0];

      // Getting the scan length.
      const Shape& operand_shape = reduce_window->inputs().front()->shape();
      int64_t scan_length =
          operand_shape.dimensions(non_trivial_window_dimension);

      // Padding size of the dimension in interest
      PaddingConfig padding_config = pad->padding_config();
      auto& padding_dim =
          padding_config.dimensions(non_trivial_window_dimension);

      // Calculate the ration of padding size to scan length to decide if the
      // optimization is worth it. If the ratio is not significant enough it
      // disturbs later optimizations (reduce-window-rewriter).
      int64_t padding_size =
          padding_dim.edge_padding_high() + padding_dim.edge_padding_low();
      double padding_ratio = static_cast<double>(padding_size) / scan_length;

      if (padding_ratio < 0.1) {
        VLOG(10) << "Not folding pad into reduce-window as the padding ratio "
                    "is not significant enough. padding_ratio: "
                 << padding_ratio;
        return absl::OkStatus();
      }
    }
  } else {
    VLOG(10) << "Not folding pad into reduce-window as there is no pad.";
    return absl::OkStatus();
  }

  VLOG(10) << "Considering folding Pad: " << pad->ToString()
           << "\ninto reduce-window: " << reduce_window->ToString()
           << (convert != nullptr
                   ? absl::StrCat("\nvia convert: ", convert->ToString())
                   : "");

  // Do not fold interior padding into ReduceWindow since the backends do not
  // support it.
  const PaddingConfig& pad_config = pad->padding_config();
  if (HasInteriorPadding(pad_config) && window_util::HasBaseDilation(window)) {
    VLOG(10) << "Not folding interior pad into base-dilated reduce-window.";
    return absl::OkStatus();
  }

  // A cropping pad does not compose with the window padding by addition.
  if (HasNegativePadding(pad_config)) {
    VLOG(10) << "Not folding negative pad into reduce-window.";
    return absl::OkStatus();
  }

  // If reduce_window already has padding, the pad value of the pad op and the
  // init value of reduce_window must match to allow folding the pad.
  const HloInstruction* pad_value = pad->operand(1);
  const HloInstruction* reduce_init_value = reduce_window->operand(1);
  if (pad_value != reduce_init_value) {
    auto literals_are_equivalent = [&] {
      auto& pad_literal = pad_value->literal();
      auto& reduce_init_literal = reduce_init_value->literal();
      if (pad_literal == reduce_init_literal) {
        return true;
      }
      auto converted_pad_literal =
          pad_literal.ConvertToShape(reduce_init_value->shape());
      if (!converted_pad_literal.ok()) {
        return false;
      }
      return converted_pad_literal.value() == reduce_init_literal;
    };
    // The pad value is usually a constant, so we handle that case and do not
    // try to get more fancy about proving equivalence in cases beyond that.
    if (pad_value->opcode() != HloOpcode::kConstant ||
        reduce_init_value->opcode() != HloOpcode::kConstant ||
        !literals_are_equivalent()) {
      VLOG(10) << "Not folding pad into reduce-window due to different pad "
                  "values.";
      return absl::OkStatus();
    }
  }

  const int64_t rank = reduce_window->shape().dimensions().size();
  TF_RET_CHECK(pad_config.dimensions().size() == rank);
  TF_RET_CHECK(window.dimensions().size() == rank);

  Window new_window = window;
  for (int64_t i = 0; i < rank; ++i) {
    const PaddingConfig::PaddingConfigDimension& pad_dim =
        pad_config.dimensions(i);
    WindowDimension& window_dim = *new_window.mutable_dimensions(i);
    window_dim.set_padding_low(window_dim.padding_low() +
                               window_dim.base_dilation() *
                                   pad_dim.edge_padding_low());
    window_dim.set_padding_high(window_dim.padding_high() +
                                window_dim.base_dilation() *
                                    pad_dim.edge_padding_high());
    if (pad_dim.interior_padding() != 0) {
      CHECK_EQ(window_dim.base_dilation(), 1);
      window_dim.set_base_dilation(1 + pad_dim.interior_padding());
    }
  }

  HloInstruction* pad_operand = pad->mutable_operand(0);

  // If the candidate window reduces a single unpadded element surrounded by
  // identity padding in every output window, then this is a broadcast.
  auto is_effective_broadcast = [&](const Window& candidate_window,
                                    const Shape& candidate_shape) {
    if (!candidate_shape.is_static() || !reduce_window->shape().is_static()) {
      return false;
    }
    for (int64_t i = 0; i < rank; ++i) {
      const WindowDimension& window_dim = candidate_window.dimensions(i);
      const int64_t operand_dim = candidate_shape.dimensions(i);
      const int64_t output_dim = reduce_window->shape().dimensions(i);
      if (operand_dim != 1) {
        if (!window_util::IsTrivialWindowDimension(window_dim) ||
            output_dim != operand_dim) {
          VLOG(10) << "Dimension not equal to 1 is not trivial: " << i;
          return false;
        }
        continue;
      }
      if (output_dim == 0) {
        continue;
      }
      if (window_dim.padding_low() < 0 || window_dim.padding_high() < 0 ||
          window_dim.window_dilation() != 1) {
        VLOG(10) << "Size 1 dimension has cropping or window dilation: " << i;
        return false;
      }
      auto [last_window_start, overflow] =
          OverflowSafeMultiply(output_dim - 1, window_dim.stride());
      if (overflow || window_dim.padding_low() >= window_dim.size() ||
          last_window_start > window_dim.padding_low()) {
        VLOG(10) << "Found window did not cover single unpadded element in "
                    "dimension: "
                 << i;
        return false;
      }
    }
    VLOG(10) << "Found window covers a single unpadded element.";
    return true;
  };

  const bool combined_bcast =
      is_effective_broadcast(new_window, pad_operand->shape());
  const bool rw_bcast =
      !combined_bcast && is_effective_broadcast(window, operand->shape());
  HloInstruction* new_reduce_window_operand = rw_bcast ? operand : pad_operand;
  if (!rw_bcast && convert != nullptr) {
    Shape changed_shape = ShapeUtil::ChangeElementType(
        pad_operand->shape(), convert->shape().element_type());
    simplifier_->UpdateLayout(&changed_shape);
    new_reduce_window_operand = hlo->AddInstruction(
        HloInstruction::CreateConvert(changed_shape, pad_operand));
  }

  if (combined_bcast || rw_bcast) {
    VLOG(10) << "Replacing pad/reduce-window with broadcast.";
    auto fadd = [this, hlo](std::unique_ptr<HloInstruction> x) {
      simplifier_->UpdateLayout(x->mutable_shape());
      return hlo->AddInstruction(std::move(x));
    };
    return ReplaceWithNewInstruction(
        reduce_window, HloInstruction::CreateBroadcastSequence(
                           /*output_shape=*/reduce_window->shape(),
                           /*operand=*/new_reduce_window_operand, fadd));
  }

  // Carry out the folding of the pad into reduce_window.
  VLOG(10) << "Folding pad into reduce-window.";
  return ReplaceWithNewInstruction(
      reduce_window, HloInstruction::CreateReduceWindow(
                         /*shape=*/reduce_window->shape(),
                         /*operand=*/new_reduce_window_operand,
                         /*init_value=*/reduce_window->mutable_operand(1),
                         /*window=*/new_window,
                         /*reduce_computation=*/function));
}

bool IsInConditionalBranch(const HloComputation* computation) {
  absl::InlinedVector<const HloComputation*, 4> worklist = {computation};
  absl::flat_hash_set<const HloComputation*> visited;
  while (!worklist.empty()) {
    const HloComputation* current = worklist.back();
    worklist.pop_back();
    for (const HloInstruction* caller : current->caller_instructions()) {
      if (caller->opcode() == HloOpcode::kConditional) {
        return true;
      }
      const HloComputation* parent = caller->parent();
      if (parent != nullptr && visited.insert(parent).second) {
        worklist.push_back(parent);
      }
    }
  }
  return false;
}

std::optional<UniformCollectiveOperand> MatchUniformCollectiveOperand(
    HloInstruction* collective, const AlgebraicSimplifierOptions& options) {
  if (!collective->shape().IsArray() || collective->operand_count() != 1 ||
      collective->HasControlDependencies() ||
      collective->parent()->IsAsyncComputation() ||
      IsInConditionalBranch(collective->parent())) {
    return std::nullopt;
  }
  if (options.is_layout_sensitive() && collective->shape().has_layout() &&
      collective->shape().layout().memory_space() == Layout::kHostMemorySpace) {
    return std::nullopt;
  }

  HloInstruction* operand = collective->mutable_operand(0);
  HloInstruction* scalar_constant = nullptr;
  if (Match(operand, m::Broadcast(m::ConstantScalar(&scalar_constant))) ||
      Match(operand, m::ConstantScalar(&scalar_constant))) {
    return UniformCollectiveOperand{scalar_constant->literal().Clone(),
                                    scalar_constant};
  }
  if (operand->opcode() == HloOpcode::kConstant &&
      !ShapeUtil::IsZeroElementArray(operand->shape()) &&
      operand->literal().IsAllFirst()) {
    return UniformCollectiveOperand{
        LiteralUtil::GetFirstScalarLiteral(operand->literal()), nullptr};
  }
  return std::nullopt;
}

std::unique_ptr<HloInstruction> CreateUniformCollectiveReplacement(
    HloInstruction* collective, UniformCollectiveOperand uniform,
    const AlgebraicSimplifierOptions& options, AlgebraicSimplifier* simplifier,
    AlgebraicSimplifierVisitor* visitor) {
  if (ShapeUtil::IsScalar(collective->shape()) &&
      (!options.is_layout_sensitive() || !collective->shape().has_layout() ||
       collective->shape().layout().memory_space() ==
           Layout::kDefaultMemorySpace)) {
    std::unique_ptr<HloInstruction> new_const =
        simplifier->CreateConstantWithLayoutUpdated(
            std::move(uniform.scalar_literal));
    if (options.is_layout_sensitive() && collective->shape().has_layout() &&
        visitor->IsValidLayout(collective->shape())) {
      *new_const->mutable_shape()->mutable_layout() =
          collective->shape().layout();
    }
    return new_const;
  }

  HloInstruction* scalar_constant = uniform.scalar_constant;
  if (scalar_constant == nullptr ||
      (options.is_layout_sensitive() && scalar_constant->shape().has_layout() &&
       scalar_constant->shape().layout().memory_space() !=
           Layout::kDefaultMemorySpace)) {
    scalar_constant = collective->parent()->AddInstruction(
        simplifier->CreateConstantWithLayoutUpdated(
            std::move(uniform.scalar_literal)));
  }
  return HloInstruction::CreateBroadcast(collective->shape(), scalar_constant,
                                         {});
}

std::unique_ptr<HloInstruction> TryRemainderToAnd(
    HloInstruction* remainder, HloComputation* computation,
    AlgebraicSimplifier* simplifier) {
  HloInstruction *a, *b, *c;
  CHECK(Match(remainder, m::Remainder(m::Op(&a), m::Op(&b))));

  if (ShapeUtil::ElementIsIntegral(remainder->shape()) &&
      !Match(b, m::ConstantEffectiveScalar(&c)) &&
      !Match(b, m::Broadcast(m::ConstantEffectiveScalar(&c)))) {
    return nullptr;
  }

  if (ShapeUtil::ElementIsSigned(remainder->shape())) {
    int64_t b_value = static_cast<int64_t>(c->literal().GetFirstElement<T>());
    if (b_value > 0 && absl::has_single_bit(static_cast<uint64_t>(b_value))) {
      // Handle negative dividends by negating the result of the division.
      HloInstruction* zero_like_a = BroadcastZeros(computation, a->shape());

      Shape compare_shape = ShapeUtil::ChangeElementType(a->shape(), PRED);
      simplifier->UpdateLayout(&compare_shape);
      auto* dividend_is_negative =
          remainder->AddInstruction(HloInstruction::CreateCompare(
              compare_shape, a, zero_like_a, ComparisonDirection::kLt));

      auto* negated_dividend = remainder->AddInstruction(
          HloInstruction::CreateUnary(a->shape(), HloOpcode::kNegate, a));

      auto* abs_dividend =
          remainder->AddInstruction(HloInstruction::CreateTernary(
              a->shape(), HloOpcode::kSelect, dividend_is_negative,
              negated_dividend, a));

      auto* quotient = remainder->AddInstruction(HloInstruction::CreateBinary(
          remainder->shape(), HloOpcode::kAnd, abs_dividend,
          MakeScalarLike(abs_dividend, b_value - 1)));

      auto* neqated_quotient =
          remainder->AddInstruction(HloInstruction::CreateUnary(
              quotient->shape(), HloOpcode::kNegate, quotient));

      return HloInstruction::CreateTernary(
          remainder->shape(), HloOpcode::kSelect, dividend_is_negative,
          neqated_quotient, quotient);
    }
  } else {
    uint64_t b_value = static_cast<uint64_t>(c->literal().GetFirstElement<T>());
    if (absl::has_single_bit(b_value)) {
      HloInstruction* mask_amount =
          remainder->AddInstruction(simplifier->CreateConstantWithLayoutUpdated(
              LiteralUtil::CreateR0<T>(static_cast<T>(b_value - 1))));
      if (!ShapeUtil::IsScalar(b->shape())) {
        mask_amount = remainder->AddInstruction(
            HloInstruction::CreateBroadcast(b->shape(), mask_amount, {}));
      }
      return HloInstruction::CreateBinary(remainder->shape(), HloOpcode::kAnd,
                                          a, mask_amount);
    }
  }
  return nullptr;
}

absl::Status AlgebraicSimplifierVisitor::HandleShuffle(HloInstruction* hlo) {
  auto* shuffle = Cast<HloShuffleInstruction>(hlo);

  switch (shuffle->mode()) {
    case ShuffleMode::kRotate: {
      // Accumulate shifts per dimension (in ascending order of dim).
      absl::btree_map<int64_t, int64_t> combined_shifts;
      for (int64_t i = 0; i < shuffle->dimensions().size(); ++i) {
        combined_shifts[shuffle->dimensions()[i]] +=
            shuffle->rotate().shifts(i);
      }

      // rotate(rotate(x, {d}, {m}), {d}, {n}) ==> rotate(x, {d}, {m + n})
      HloInstruction* base_operand = shuffle->mutable_operand(0);
      while (base_operand->opcode() == HloOpcode::kShuffle &&
             Cast<HloShuffleInstruction>(base_operand)->mode() ==
                 ShuffleMode::kRotate) {
        auto* inner_shuffle = Cast<HloShuffleInstruction>(base_operand);
        for (int64_t i = 0; i < inner_shuffle->dimensions().size(); ++i) {
          combined_shifts[inner_shuffle->dimensions()[i]] +=
              inner_shuffle->rotate().shifts(i);
        }
        base_operand = inner_shuffle->mutable_operand(0);
      }

      // Helper to check if base_operand is a splat along dim.
      auto is_dim_splat = [&](int64_t dim) -> bool {
        if (base_operand->IsConstant() &&
            base_operand->literal().IsAllFirst()) {
          return true;
        }
        if (base_operand->opcode() == HloOpcode::kBroadcast) {
          return !absl::c_linear_search(base_operand->dimensions(), dim);
        }
        return false;
      };

      // Canonicalize shifts & dimensions, remove no-op dims.
      DimensionVector new_dimensions;
      DimensionVector new_shifts;
      for (const auto& [dim, total_shift] : combined_shifts) {
        int64_t dim_size = shuffle->shape().dimensions(dim);
        // No-op: size 1 dim
        if (dim_size <= 1) {
          continue;
        }
        // No-op: splat along dim
        if (is_dim_splat(dim)) {
          continue;
        }
        int64_t norm_shift = shuffle::NormalizeShift(total_shift, dim_size);
        // No-op: shift == 0
        if (norm_shift == 0) {
          continue;
        }
        new_dimensions.push_back(dim);
        new_shifts.push_back(norm_shift);
      }

      // Replace if changed.
      if (new_dimensions.empty()) {
        return ReplaceInstruction(shuffle, base_operand);
      }
      if (base_operand != shuffle->operand(0) ||
          new_dimensions != shuffle->dimensions() ||
          !absl::c_equal(new_shifts, shuffle->rotate().shifts())) {
        auto new_shuffle = HloInstruction::CreateShuffle(
            shuffle->shape(), base_operand, new_dimensions,
            shuffle::Rotate(new_shifts));
        return ReplaceWithNewInstruction(shuffle, std::move(new_shuffle));
      }
      return absl::OkStatus();
    }
    default:
      return absl::OkStatus();
  }
}

